//! The generated TypeScript module: exact types, a typed call table, and a
//! client that speaks the bridge.
//!
//! Types come from the WIT, not from the OpenAPI document, because the document
//! cannot say which response belongs to which call. The call table can, and it
//! is the whole reason a skin is generated rather than hand-written.

use std::fmt::Write as _;

use crate::schema;
use crate::{Api, ApiFunction, Shape};

pub fn client(api: &Api) -> String {
    let mut out = String::new();
    let _ = writeln!(
        out,
        "// Generated by `cargo run -p soil-openapi -- --package {} --out <dir>`.",
        api.package
    );
    let _ = writeln!(
        out,
        "// Source: {}@{} (WIT). Do not edit; regenerate instead.",
        api.package, api.version
    );
    out.push('\n');

    for ty in &api.types {
        doc(&mut out, ty.docs.as_deref(), "");
        match &ty.shape {
            Shape::Record(fields) => {
                let _ = writeln!(out, "export interface {} {{", ty.ts);
                for field in fields {
                    let note = match field.shape {
                        Shape::Bytes => Some("Base64-encoded."),
                        _ => None,
                    };
                    let docs = match (field.docs.as_deref(), note) {
                        (Some(docs), Some(note)) => Some(format!("{docs} {note}")),
                        (None, Some(note)) => Some(note.to_owned()),
                        (Some(docs), None) => Some(docs.to_owned()),
                        (None, None) => None,
                    };
                    doc(&mut out, docs.as_deref(), "  ");
                    let _ = writeln!(out, "  {}: {};", field.ts, schema::ts(&field.shape));
                }
                out.push_str("}\n\n");
            }
            shape => {
                let _ = writeln!(out, "export type {} = {};\n", ty.ts, schema::ts(shape));
            }
        }
    }

    let code = api
        .types
        .iter()
        .find(|ty| ty.name == "error")
        .map(|ty| ty.ts.clone())
        .unwrap_or_else(|| "string".into());
    let _ = writeln!(
        out,
        "/** The bridge's typed error. `code` is the WIT `error` enum. */\nexport interface BridgeError {{ code: {code}; message: string }}\n"
    );

    out.push_str(EVENTS);

    // Computed before both the call table and the methods so the two agree: the
    // table says what the bridge *accepts*, and a write-only field the host
    // assigns is optional on the way in.
    let alias = write_only_alias(api);

    out.push_str("export interface Operations {\n");
    for function in &api.functions {
        let operation = format!("{}.{}", api.package, function.name);
        let _ = writeln!(
            out,
            "  \"{operation}\": {{ params: {}; ok: {} }};",
            params_type(function, replace_for(&alias, &function.name)),
            schema::ts(&function.ok)
        );
    }
    out.push_str("}\n\n");

    if let Some((_, _, declaration)) = &alias {
        out.push_str(declaration);
    }

    out.push_str(CLIENT_HEAD);

    for function in &api.functions {
        if function.name == "call" || function.name == "session" {
            continue;
        }
        write_method(&mut out, api, function, replace_for(&alias, &function.name));
    }

    out.push_str(CLIENT_TAIL);
    out
}

fn replace_for<'a>(
    alias: &'a Option<(String, String, String)>,
    name: &str,
) -> Option<(&'a str, &'a str)> {
    match (alias, name) {
        (Some((alias_name, entry, _)), "upsert") => Some((entry.as_str(), alias_name.as_str())),
        _ => None,
    }
}

fn write_method(
    out: &mut String,
    api: &Api,
    function: &ApiFunction,
    replace: Option<(&str, &str)>,
) {
    let operation = format!("{}.{}", api.package, function.name);
    let method = crate::camel(&function.name);
    let summary = function
        .docs
        .clone()
        .unwrap_or_else(|| function.name.clone())
        .split_whitespace()
        .collect::<Vec<_>>()
        .join(" ")
        .replace("*/", "*\\/");
    let _ = writeln!(
        out,
        "\n  /** {} */\n  {}(params: {}) {{\n    return this.call(\"{operation}\", params);\n  }}",
        summary,
        method,
        params_type(function, replace)
    );
}

fn params_type(function: &ApiFunction, replace: Option<(&str, &str)>) -> String {
    if function.params.is_empty() {
        return "Record<string, never>".into();
    }
    let fields = function
        .params
        .iter()
        .map(|param| {
            let name = match param.shape {
                Shape::Optional(_) => format!("{}?", param.ts),
                _ => param.ts.clone(),
            };
            let ty = match (&param.shape, replace) {
                (Shape::Named(named), Some((from, to))) if named == from => to.to_owned(),
                _ => schema::ts(&param.shape),
            };
            format!("{name}: {ty}")
        })
        .collect::<Vec<_>>()
        .join("; ");
    format!("{{ {fields} }}")
}

fn doc(out: &mut String, docs: Option<&str>, indent: &str) {
    let Some(docs) = docs else {
        return;
    };
    let _ = write!(out, "{indent}/** ");
    for (index, line) in docs.lines().enumerate() {
        if index > 0 {
            let _ = write!(out, "\n{indent} * ");
        }
        let _ = write!(out, "{}", line.trim());
    }
    out.push_str(" */\n");
}

/// `soil:records` assigns `revision`, `updatedAtMs`, `origin` and `deleted`
/// itself; the WIT carries them on the same `entry` type because an upsert hands
/// back what it stored. A caller should not have to invent them to write.
fn write_only_alias(api: &Api) -> Option<(String, String, String)> {
    if api.package != "soil:records" {
        return None;
    }
    let entry = api.types.iter().find(|ty| ty.name == "entry")?.ts.clone();
    let fields: Vec<String> = match api
        .types
        .iter()
        .find(|ty| ty.name == "entry")?
        .shape
        .clone()
    {
        Shape::Record(fields) => fields.into_iter().map(|field| field.ts).collect(),
        _ => return None,
    };
    let assigned: Vec<&str> = ["revision", "updatedAtMs", "origin", "deleted"]
        .into_iter()
        .filter(|name| fields.iter().any(|field| field == name))
        .collect();
    if assigned.is_empty() {
        return None;
    }
    let alias = format!("New{entry}");
    let keys = assigned
        .iter()
        .map(|name| format!("\"{name}\""))
        .collect::<Vec<_>>()
        .join(" | ");
    let declaration = format!(
        "/** An entry to write: the host assigns {}. */\nexport type {alias} = Omit<{entry}, {keys}> & Partial<Pick<{entry}, {keys}>>;\n\n",
        assigned.join(", ")
    );
    Some((alias, entry, declaration))
}

const EVENTS: &str = r#"/** One frame on a session. `ready` carries the host's grants and bindings. */
export type BridgeEvent =
  | { kind: "ready"; spore: string; grants: string[]; interfaces: Record<string, unknown>; session?: string }
  | { kind: "changed"; collection: string; id: string; revision: number };

"#;

const CLIENT_HEAD: &str = r#"export interface BridgeCall {
  id: string;
  interface: string;
  function: string;
  params: unknown;
}

/** One frame either way. `call` is the host asking the page to do something. */
export type BridgeFrame =
  | { v: 1; event: BridgeEvent }
  | { v: 1; call: BridgeCall }
  | { v: 1; cancel: { id: string } };

export type SessionHandlers = {
  onEvent?: (event: BridgeEvent) => void;
  /** Raw frames, including a host call a providing page may answer. */
  onFrame?: (frame: BridgeFrame) => void;
  onOpen?: () => void;
  onClose?: () => void;
};

/**
 * A browser client for one Spore's bridge.
 *
 * `base` is the bridge origin ("" for same-origin). `token` is only needed when
 * the bridge was started with `--token`.
 *
 * `events()` is the one that always works: server-sent events and POSTs travel
 * through any HTTP proxy, while a WebSocket upgrade is dropped by the ones that
 * strip hop-by-hop headers. `session()` is the same protocol over a socket,
 * where one is available.
 */
export class BridgeClient {
  constructor(
    readonly base = "",
    private readonly token?: string,
  ) {}

  private origin(): string {
    if (this.base) return this.base;
    return typeof location === "undefined" ? "http://127.0.0.1:8795" : location.href;
  }

  private headers(): Record<string, string> {
    return {
      "content-type": "application/json",
      ...(this.token ? { authorization: `Bearer ${this.token}` } : {}),
    };
  }

  async call<K extends keyof Operations>(
    operation: K,
    params: Operations[K]["params"],
  ): Promise<Operations[K]["ok"]> {
    const split = String(operation).lastIndexOf(".");
    const iface = String(operation).slice(0, split);
    const fn = String(operation).slice(split + 1);
    const response = await fetch(new URL("/v1/call", this.origin()), {
      method: "POST",
      headers: this.headers(),
      body: JSON.stringify({
        v: 1,
        call: { id: crypto.randomUUID(), interface: iface, function: fn, params },
      }),
    });
    if (!response.ok) {
      throw new Error(`bridge: ${response.status} ${await response.text()}`);
    }
    const frame = await response.json();
    if (frame.result.err) {
      throw Object.assign(new Error(frame.result.err.message), frame.result.err);
    }
    return frame.result.ok;
  }

  /** Events over SSE. Returns a disposer; EventSource reconnects on its own. */
  events(handlers: SessionHandlers): () => void {
    const url = new URL("/v1/events", this.origin());
    if (this.token) url.searchParams.set("token", this.token);
    const source = new EventSource(url);
    source.onopen = () => handlers.onOpen?.();
    source.onerror = () => handlers.onClose?.();
    source.onmessage = (message) => {
      const frame = JSON.parse(String(message.data)) as BridgeFrame;
      if (frame.v !== 1) return;
      handlers.onFrame?.(frame);
      if ("event" in frame) handlers.onEvent?.(frame.event);
    };
    return () => source.close();
  }

  /** Send one client frame on an SSE session. */
  async frame(session: string, frame: unknown): Promise<unknown> {
    const url = new URL("/v1/frame", this.origin());
    url.searchParams.set("session", session);
    if (this.token) url.searchParams.set("token", this.token);
    const response = await fetch(url, {
      method: "POST",
      headers: this.headers(),
      body: JSON.stringify(frame),
    });
    if (!response.ok) {
      throw new Error(`bridge: ${response.status} ${await response.text()}`);
    }
    return response.json();
  }

  /** Events over a WebSocket. Returns a disposer; the caller owns reconnection. */
  session(handlers: SessionHandlers): () => void {
    const url = new URL("/v1/session", this.origin());
    url.protocol = url.protocol === "https:" ? "wss:" : "ws:";
    if (this.token) url.searchParams.set("token", this.token);
    const socket = new WebSocket(url);
    socket.onopen = () => handlers.onOpen?.();
    socket.onclose = () => handlers.onClose?.();
    socket.onmessage = (message) => {
      const frame = JSON.parse(String(message.data)) as BridgeFrame;
      if (frame.v !== 1) return;
      handlers.onFrame?.(frame);
      if ("event" in frame) handlers.onEvent?.(frame.event);
    };
    return () => socket.close();
  }
"#;

const CLIENT_TAIL: &str = "}\n";
